-- Pandora Worker A / Worker I: exact trusted-primitive composition and upgrade lineage.
-- Control-plane only. Stores immutable identities/evidence references, never credential values.
create table if not exists public.pandora_project_version_compositions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,project_id uuid not null references public.projectos_projects(id) on delete cascade,project_version_id uuid not null references public.pandora_project_versions(id) on delete cascade,manifest_digest text not null,materialization_plan_digest text null,upgrade_plan_digest text null,primitive_count integer not null,created_at timestamptz not null default now(),constraint pandora_project_version_compositions_manifest_check check(manifest_digest~'^sha256:[0-9a-f]{64}$'),constraint pandora_project_version_compositions_materialization_check check(materialization_plan_digest is null or materialization_plan_digest~'^sha256:[0-9a-f]{64}$'),constraint pandora_project_version_compositions_upgrade_check check(upgrade_plan_digest is null or upgrade_plan_digest~'^sha256:[0-9a-f]{64}$'),constraint pandora_project_version_compositions_count_check check(primitive_count between 1 and 256),unique(project_version_id));
create table if not exists public.pandora_project_version_primitives(id uuid primary key default gen_random_uuid(),composition_id uuid not null references public.pandora_project_version_compositions(id) on delete cascade,organization_id uuid not null references public.organizations(id) on delete cascade,project_id uuid not null references public.projectos_projects(id) on delete cascade,project_version_id uuid not null references public.pandora_project_versions(id) on delete cascade,primitive_name text not null,primitive_version text not null,trust_state text not null,definition_digest text not null,source_digest text not null,configuration_digest text not null,customization_digest text not null,verification_evidence_id uuid null references public.pandora_verification_evidence(id) on delete set null,created_at timestamptz not null default now(),constraint pandora_project_version_primitives_name_check check(primitive_name~'^pandora-[a-z0-9-]+$'),constraint pandora_project_version_primitives_version_check check(primitive_version~'^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(-[0-9A-Za-z.-]+)?$'),constraint pandora_project_version_primitives_trust_check check(trust_state in('EXPERIMENTAL','TRUSTED','DEPRECATED','BLOCKED')),constraint pandora_project_version_primitives_definition_check check(definition_digest~'^sha256:[0-9a-f]{64}$'),constraint pandora_project_version_primitives_source_check check(source_digest~'^sha256:[0-9a-f]{64}$'),constraint pandora_project_version_primitives_configuration_check check(configuration_digest~'^sha256:[0-9a-f]{64}$'),constraint pandora_project_version_primitives_customization_check check(customization_digest~'^sha256:[0-9a-f]{64}$'),unique(project_version_id,primitive_name));
create table if not exists public.pandora_primitive_upgrade_lineage(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,project_id uuid not null references public.projectos_projects(id) on delete cascade,from_project_version_id uuid not null references public.pandora_project_versions(id) on delete restrict,to_project_version_id uuid not null references public.pandora_project_versions(id) on delete cascade,primitive_name text not null,from_version text not null,to_version text not null,decision text not null,outcome text not null,upgrade_plan_digest text not null,migration_set_digest text null,rollback_plan_digest text null,forward_fix_digest text null,verification_evidence_id uuid null references public.pandora_verification_evidence(id) on delete set null,created_at timestamptz not null default now(),constraint pandora_primitive_upgrade_lineage_name_check check(primitive_name~'^pandora-[a-z0-9-]+$'),constraint pandora_primitive_upgrade_lineage_from_version_check check(from_version~'^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(-[0-9A-Za-z.-]+)?$'),constraint pandora_primitive_upgrade_lineage_to_version_check check(to_version~'^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(-[0-9A-Za-z.-]+)?$'),constraint pandora_primitive_upgrade_lineage_decision_check check(decision in('AUTO','MANUAL_REVIEW','BLOCKED')),constraint pandora_primitive_upgrade_lineage_outcome_check check(outcome in('PLANNED','APPLIED','VERIFIED','FAILED','ROLLED_BACK','FORWARD_FIXED','BLOCKED')),constraint pandora_primitive_upgrade_lineage_plan_check check(upgrade_plan_digest~'^sha256:[0-9a-f]{64}$'),constraint pandora_primitive_upgrade_lineage_migration_check check(migration_set_digest is null or migration_set_digest~'^sha256:[0-9a-f]{64}$'),constraint pandora_primitive_upgrade_lineage_rollback_check check(rollback_plan_digest is null or rollback_plan_digest~'^sha256:[0-9a-f]{64}$'),constraint pandora_primitive_upgrade_lineage_forward_fix_check check(forward_fix_digest is null or forward_fix_digest~'^sha256:[0-9a-f]{64}$'),constraint pandora_primitive_upgrade_lineage_version_change_check check(from_version<>to_version),unique(to_project_version_id,primitive_name));
create or replace function private.pandora_validate_primitive_lineage() returns trigger language plpgsql security definer set search_path='' as $$declare v_org uuid;v_project uuid;v_version uuid;v_evidence_org uuid;v_evidence_project uuid;begin if tg_table_name='pandora_project_version_compositions' then select organization_id,project_id,id into v_org,v_project,v_version from public.pandora_project_versions where id=new.project_version_id;if v_version is null or v_org<>new.organization_id or v_project<>new.project_id then raise exception 'primitive composition project-version lineage mismatch' using errcode='23514';end if;elsif tg_table_name='pandora_project_version_primitives' then select organization_id,project_id,project_version_id into v_org,v_project,v_version from public.pandora_project_version_compositions where id=new.composition_id;if v_version is null or v_org<>new.organization_id or v_project<>new.project_id or v_version<>new.project_version_id then raise exception 'primitive row composition lineage mismatch' using errcode='23514';end if;elsif tg_table_name='pandora_primitive_upgrade_lineage' then select organization_id,project_id into v_org,v_project from public.pandora_project_versions where id=new.from_project_version_id;if v_org is null or v_org<>new.organization_id or v_project<>new.project_id then raise exception 'primitive upgrade source-version lineage mismatch' using errcode='23514';end if;select organization_id,project_id into v_org,v_project from public.pandora_project_versions where id=new.to_project_version_id;if v_org is null or v_org<>new.organization_id or v_project<>new.project_id then raise exception 'primitive upgrade target-version lineage mismatch' using errcode='23514';end if;end if;if to_jsonb(new)?'verification_evidence_id' and(to_jsonb(new)->>'verification_evidence_id') is not null then select organization_id,project_id into v_evidence_org,v_evidence_project from public.pandora_verification_evidence where id=(to_jsonb(new)->>'verification_evidence_id')::uuid;if v_evidence_org is null or v_evidence_org<>new.organization_id or v_evidence_project<>new.project_id then raise exception 'primitive verification evidence lineage mismatch' using errcode='23514';end if;end if;return new;end;$$;
drop trigger if exists pandora_project_version_compositions_lineage_guard on public.pandora_project_version_compositions;create trigger pandora_project_version_compositions_lineage_guard before insert or update on public.pandora_project_version_compositions for each row execute function private.pandora_validate_primitive_lineage();drop trigger if exists pandora_project_version_primitives_lineage_guard on public.pandora_project_version_primitives;create trigger pandora_project_version_primitives_lineage_guard before insert or update on public.pandora_project_version_primitives for each row execute function private.pandora_validate_primitive_lineage();drop trigger if exists pandora_primitive_upgrade_lineage_guard on public.pandora_primitive_upgrade_lineage;create trigger pandora_primitive_upgrade_lineage_guard before insert or update on public.pandora_primitive_upgrade_lineage for each row execute function private.pandora_validate_primitive_lineage();
alter table public.pandora_project_version_compositions enable row level security;alter table public.pandora_project_version_compositions force row level security;alter table public.pandora_project_version_primitives enable row level security;alter table public.pandora_project_version_primitives force row level security;alter table public.pandora_primitive_upgrade_lineage enable row level security;alter table public.pandora_primitive_upgrade_lineage force row level security;revoke all on public.pandora_project_version_compositions from anon,authenticated;revoke all on public.pandora_project_version_primitives from anon,authenticated;revoke all on public.pandora_primitive_upgrade_lineage from anon,authenticated;grant select on public.pandora_project_version_compositions to authenticated;grant select on public.pandora_project_version_primitives to authenticated;grant select on public.pandora_primitive_upgrade_lineage to authenticated;
drop policy if exists pandora_project_version_compositions_member_read on public.pandora_project_version_compositions;create policy pandora_project_version_compositions_member_read on public.pandora_project_version_compositions for select to authenticated using(private.is_org_member(organization_id));drop policy if exists pandora_project_version_primitives_member_read on public.pandora_project_version_primitives;create policy pandora_project_version_primitives_member_read on public.pandora_project_version_primitives for select to authenticated using(private.is_org_member(organization_id));drop policy if exists pandora_primitive_upgrade_lineage_member_read on public.pandora_primitive_upgrade_lineage;create policy pandora_primitive_upgrade_lineage_member_read on public.pandora_primitive_upgrade_lineage for select to authenticated using(private.is_org_member(organization_id));revoke all on function private.pandora_validate_primitive_lineage() from public,anon,authenticated;
